css:
.hjc-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.hjc-root,.hjc-root *,.hjc-root *::before,.hjc-root *::after{box-sizing:border-box}
.hjc-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.hjc-root img{display:block;border:0;max-width:none}
.hjc-root [hidden]{display:none!important}
.hjc-root .n65_3352{background-color:var(--wa-surface, #1a1e2b);align-content:stretch;cursor:pointer;display:flex;gap:10px;height:25px;align-items:center;padding-left:5px;position:relative;border-radius:2px;flex-shrink:0;width:132px;border-style:solid;border-color:var(--wa-line, #565e71);border-width:1px}
.hjc-root .x232{background-color:var(--wa-surface, #414a64);align-content:stretch;display:flex;height:16px;align-items:center;justify-content:center;position:relative;flex-shrink:0;width:34px;filter:drop-shadow(2.828px 2.828px 0px rgba(0,0,0,0.35))}
.hjc-root .x233{word-break:break-word;font-family:"Dinbol","Pretendard",sans-serif;font-weight:400;line-height:normal;font-style:normal;position:relative;flex-shrink:0;font-size:11px;text-align:left;color:var(--wa-text, #fff);white-space:nowrap}
.hjc-root .x234{word-break:break-word;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:400;line-height:normal;font-style:normal;position:relative;flex-shrink:0;font-size:10px;color:color-mix(in srgb, var(--wa-text, rgb(255 255 255)) 50%, transparent);text-align:left;white-space:nowrap}
.hjc-root[data-theme="light"]{background:var(--wa-bg, #e9edf5);color:var(--wa-text, #141a28)}
.hjc-root[data-theme="light"] .n65_3352{background-color:var(--wa-bg, #ffffff);border-color:var(--wa-line, #c4ccdc)}
.hjc-root[data-theme="light"] .x232{background-color:var(--wa-point, #dbe1ee)}
.hjc-root[data-theme="light"] .x233{color:var(--wa-text, #141a28)}
.hjc-root[data-theme="light"] .x234{color:color-mix(in srgb, var(--wa-text, rgb(20 26 40)) 55%, transparent)}
